import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Building and Scaling Data Pipelines for Data Engineering With Ceph Object Storage - Kyle Bader, IBM","description":"","frontmatter":{"title":"Building and Scaling Data Pipelines for Data Engineering With Ceph Object Storage - Kyle Bader, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph对象存储","数据管道","数据工程","事件驱动架构","无服务器框架"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Building_and_Scaling_Data_Pipelines_for_Data_Engineering_With_Ceph_Object_Storage_-_Kyle_Bader_IBM.md","filePath":"posts/2023/Building_and_Scaling_Data_Pipelines_for_Data_Engineering_With_Ceph_Object_Storage_-_Kyle_Bader_IBM.md","lastUpdated":1780459816000}'),_={name:"posts/2023/Building_and_Scaling_Data_Pipelines_for_Data_Engineering_With_Ceph_Object_Storage_-_Kyle_Bader_IBM.md"};function r(l,e,o,g,s,p){return n(),i("div",null,[...e[0]||(e[0]=[a("<p>在本次会议中，IBM首席产品架构师Kyle Bader详细介绍了Ceph对象存储在数据管道中的应用，探讨了如何通过Ceph实现高效的数据处理和分析。</p><p><strong>主要内容</strong>：</p><ol><li><strong>数据处理新常态</strong>：随着数据分析和处理转向对象存储，Ceph等对象存储系统成为数据管理的标准。</li><li><strong>对象存储的多功能性</strong>：Ceph的RADOS Gateway支持S3和Swift API，以及NFS服务，支持复杂的数据工程任务。</li><li><strong>数据湖应用多样性</strong>：Ceph支持直接通过S3 API交互的应用、流技术如Kafka，以及其他数据分析和处理工具。</li><li><strong>事件驱动架构</strong>：Ceph支持桶通知功能，可以将事件发送到Kafka、AMQ或REST API，实现事件驱动的数据处理。</li><li><strong>实际应用案例</strong>：展示了基于医疗影像分析的案例，利用Ceph的事件通知功能和无服务器计算进行肺炎风险分析。</li><li><strong>安全与访问控制</strong>：Ceph的STS和IAM实现支持基于属性的访问控制（ABAC），通过OpenID Connect提供者实现更精细的权限管理。</li><li><strong>未来展望</strong>：持续关注和利用Ceph的S3 API扩展功能，以实现更高级的数据管理任务。</li></ol><p><strong>讨论与问答</strong>：</p><ul><li><strong>S3用户与主体令牌的映射</strong>：通过IAM API定义角色，并在桶策略中使用角色而不是具体的用户名。</li><li><strong>数据管道的适用性</strong>：数据管道主要针对对象存储，但可以通过某些功能扩展到其他存储类型。</li><li><strong>批处理的挑战</strong>：Ceph的事件驱动架构可以部分解决批处理中的分布式和并发问题。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>提供详细的文档和示例代码，帮助用户理解和实施Ceph对象存储的高级功能。</li><li>探索将事件驱动架构扩展到其他存储类型的可能性。</li></ul>",7)])])}const S=t(_,[["render",r]]);export{c as __pageData,S as default};
